SELECT 


    d.kind = #{kind}
    AND d.delivery_no LIKE CONCAT('%', #{q.keyword}, '%')

        AND x.status IN #{st}

    AND (d.from_store_id = #{q.storeId} OR d.to_store_id = #{q.storeId})
    AND d.receive_date >= #{q.begin}
    AND d.receive_date <= #{q.end}
    AND x.material_id = #{q.materialId}

ORDER BY x.id DESC

SELECT 

WHERE d.id = #{deliveryId}
ORDER BY x.id
